import json,csv,re
tr={}
for l in open('data/judge_transcripts.jsonl'):
    r=json.loads(l); tr[r['rating_id']]=r
rows=list(csv.DictReader(open('data/scores.csv')))
mism=[];
for r in rows:
    t=tr.get(r['rating_id'])
    if t is None: mism.append(('missing',r['rating_id'])); continue
    m=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    if not m or int(m[-1])!=int(r['score']) or t['response_id']!=r['response_id'] or t['displayed_label']!=r['displayed_label'] or t['session']!=int(r['session']):
        mism.append((r['rating_id'],r['score'],m,t['response_id'],r['response_id'],t['displayed_label'],r['displayed_label'],t['session'],r['session']))
print(len(rows),len(tr),mism)
# judge models and other anomalies
from collections import Counter
print(Counter((t['judge_model'],t['displayed_label'],t['session']) for t in tr.values()))
for t in tr.values():
    if len(re.findall(r'FINAL SCORE',t['judge_output']))!=1 or 'Displayed author' not in t['judge_output']:
        print(t)

